#ifndef VK_RADIX_SORT_VULKAN_BENCHMARK_H
#define VK_RADIX_SORT_VULKAN_BENCHMARK_H

#include "benchmark_base.h"

#include "volk.h"
#include "vk_mem_alloc.h"
#include "vk_radix_sort.h"

class VulkanBenchmark : public BenchmarkBase {
 private:
  struct Buffer {
    VkBufferUsageFlags usage = 0;
    VkDeviceSize size = 0;
    VkBuffer buffer = VK_NULL_HANDLE;
    VmaAllocation allocation = VK_NULL_HANDLE;
    uint8_t* map = nullptr;
  };

 public:
  VulkanBenchmark();
  ~VulkanBenchmark() override;

  std::string LibraryVersion() const override;

  Results Sort(const std::vector<uint32_t>& keys) override;
  Results SortKeyValue(const std::vector<uint32_t>& keys,
                       const std::vector<uint32_t>& values) override;

 protected:
  void Reallocate(Buffer* buffer, VkDeviceSize size, VkBufferUsageFlags usage, bool mapped = false);

 private:
  VkInstance instance_ = VK_NULL_HANDLE;
  VkDebugUtilsMessengerEXT messenger_ = VK_NULL_HANDLE;
  VkPhysicalDevice physical_device_ = VK_NULL_HANDLE;
  uint32_t queue_family_index_ = 0;
  VkDevice device_ = VK_NULL_HANDLE;
  VkQueue queue_ = VK_NULL_HANDLE;
  VmaAllocator allocator_ = VK_NULL_HANDLE;
  VkCommandPool command_pool_ = VK_NULL_HANDLE;
  VkCommandBuffer command_buffer_ = VK_NULL_HANDLE;
  VkFence fence_ = VK_NULL_HANDLE;
  VkQueryPool query_pool_ = VK_NULL_HANDLE;

  VrdxSorter sorter_ = VK_NULL_HANDLE;
  Buffer keys_;
  Buffer storage_;
  Buffer staging_;
};

#endif  // VK_RADIX_SORT_VULKAN_BENCHMARK_H

#include "benchmark_factory.h"

#include <stdexcept>

#include "cpu_benchmark.h"
#include "vulkan_benchmark.h"

#ifdef BENCH_CUDA
#include "cuda_benchmark.h"
#endif

#ifdef BENCH_EMBREE_CUDA
#include "embree_cuda_benchmark.h"
#endif

std::unique_ptr<BenchmarkBase> BenchmarkFactory::Create(const std::string& type) {
  if (type == "cpu") return std::make_unique<CpuBenchmark>();
  if (type == "vulkan") return std::make_unique<VulkanBenchmark>();

#ifdef BENCH_CUDA
  if (type == "cuda") return std::make_unique<CudaBenchmark>();
#endif

#ifdef BENCH_EMBREE_CUDA
  if (type == "embree-cuda") return std::make_unique<EmbreeCudaBenchmark>();
#endif

  throw std::runtime_error("Unavailable benchmark type: " + type);
}

