#ifndef VK_RADIX_SORT_VULKAN_BENCHMARK_H
#define VK_RADIX_SORT_VULKAN_BENCHMARK_H

#include "benchmark_base.h"

#include "volk.h"
#include "vk_mem_alloc.h"
#include "vk_radix_sort.h"

class VulkanBenchmark : public BenchmarkBase {
