1	#include "MultiRadixSort.h"
2	
3	namespace engine {
4	
5	    void MultiRadixSort::execute(GPUContext *gpuContext, uint32_t numElements) {
6	        // gpu context
7	        m_gpuContext = gpuContext;
8	        m_numElements = numElements;
9	
10	        // compute pass
11	        m_pass = std::make_shared<MultiRadixSortPass>(gpuContext);
12	        m_pass->create();
13	        const uint32_t NUM_BLOCKS_PER_WORKGROUP = 32;
14	        uint32_t globalInvocationSize = m_numElements / NUM_BLOCKS_PER_WORKGROUP;
15	        uint32_t remainder = m_numElements % NUM_BLOCKS_PER_WORKGROUP;
16	        globalInvocationSize += remainder > 0 ? 1 : 0;
17	        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, globalInvocationSize, 1, 1);
18	        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT, globalInvocationSize, 1, 1);
19	
20	        // push constants
21	        const uint32_t NUM_WORKGROUPS = m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width;
22	        assert(NUM_WORKGROUPS == m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT).width);
23	        m_pass->m_pushConstantsHistogram.g_num_elements = m_numElements;
24	        m_pass->m_pushConstantsHistogram.g_num_workgroups = NUM_WORKGROUPS;
25	        m_pass->m_pushConstantsHistogram.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
26	        m_pass->m_pushConstants.g_num_elements = m_numElements;
27	        m_pass->m_pushConstants.g_num_workgroups = NUM_WORKGROUPS;
28	        m_pass->m_pushConstants.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
29	
30	        // buffers
31	        prepareBuffers();
32	        std::cout << PRINT_PREFIX << "Sorting " << m_numElements << " " << (sizeof(m_elementsIn[0]) * 8) << "bit numbers." << std::endl;
33	
34	        // set storage buffers
35	        uint32_t activeIndex = m_gpuContext->getActiveIndex();
36	
37	        // m_buffer0
38	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[0].get()); // iteration 0 and 2 (0,0)
39	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[0].get());            // iteration 0 and 2 (1,0)
40	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[0].get());  // iteration 1 and 3 (1,1)
41	
42	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[1].get()); // iteration 1 and 3 (0,0)
43	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[1].get());                      // iteration 0 and 2 (1,1)
44	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[1].get());            // iteration 1 and 3 (1,0)
45	
46	        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 1, m_buffers[2].get());
47	        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT, 2, m_buffers[2].get());
48	
49	        // execute pass
50	        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
51	        VkSemaphore awaitBeforeExecution = VK_NULL_HANDLE;
52	#ifdef SORT_32BIT
53	        const uint32_t NUM_ITERATIONS = 4;
54	#else
55	        const uint32_t NUM_ITERATIONS = 8;
56	#endif
57	        if (m_gpuContext->m_timestampPeriod <= 0.0f || m_gpuContext->m_computeTimestampValidBits == 0) {
58	            throw std::runtime_error("Compute queue does not support valid timestamp queries!");
59	        }
60	
61	        const uint32_t TIMESTAMP_QUERIES_PER_ITERATION = 2;
62	        const uint32_t timestampQueryCount = NUM_ITERATIONS * TIMESTAMP_QUERIES_PER_ITERATION;
63	        VkQueryPoolCreateInfo queryPoolInfo{};
64	        queryPoolInfo.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO;
65	        queryPoolInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
66	        queryPoolInfo.queryCount = timestampQueryCount;
67	
68	        struct QueryPoolGuard {
69	            VkDevice device = VK_NULL_HANDLE;
70	            VkQueryPool pool = VK_NULL_HANDLE;
71	            ~QueryPoolGuard() {
72	                if (pool != VK_NULL_HANDLE) vkDestroyQueryPool(device, pool, nullptr);
73	            }
74	        } timestampQueries{m_gpuContext->m_device};
75	
76	        if (vkCreateQueryPool(m_gpuContext->m_device, &queryPoolInfo, nullptr, &timestampQueries.pool) != VK_SUCCESS) {
77	            throw std::runtime_error("Failed to create timestamp query pool!");
78	        }
79	        vkResetQueryPool(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount);
80	
81	        for (uint32_t i = 0; i < NUM_ITERATIONS; i++) {
82	            m_pass->m_pushConstantsHistogram.g_shift = 8 * i;
83	            m_pass->m_pushConstants.g_shift = 8 * i;
84	            const uint32_t queryBase = i * TIMESTAMP_QUERIES_PER_ITERATION;
85	            awaitBeforeExecution = m_pass->execute(awaitBeforeExecution, timestampQueries.pool, queryBase, queryBase + 1);
86	            m_gpuContext->incrementActiveIndex();
87	        }
88	        vkQueueWaitIdle(m_gpuContext->m_queues->getQueue(Queues::COMPUTE));
89	        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
90	        double gpuSortTime = (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));
91	
92	        std::vector<uint64_t> timestamps(timestampQueryCount);
93	        if (vkGetQueryPoolResults(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount, timestamps.size() * sizeof(uint64_t), timestamps.data(), sizeof(uint64_t), VK_QUERY_RESULT_64_BIT | VK_QUERY_RESULT_WAIT_BIT) != VK_SUCCESS) {
94	            throw std::runtime_error("Failed to read timestamp query results!");
95	        }
96	
97	        const uint64_t timestampMask = m_gpuContext->m_computeTimestampValidBits == 64 ? ~0ull : ((1ull << m_gpuContext->m_computeTimestampValidBits) - 1ull);
98	        const auto timestampDeltaMs = [&](uint64_t start, uint64_t end) {
99	            start &= timestampMask;
100	            end &= timestampMask;
101	            const uint64_t delta = end >= start ? end - start : timestampMask - start + end + 1;
102	            return static_cast<double>(delta) * m_gpuContext->m_timestampPeriod / 1000000.0;
103	        };
104	
105	        double gpuTimestampSumMs = 0.0;
106	        for (uint32_t i = 0; i < NUM_ITERATIONS; ++i) {
107	            const uint64_t start = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION];
108	            const uint64_t end = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION + 1];
109	            gpuTimestampSumMs += timestampDeltaMs(start, end);
110	        }
111	        const double gpuTimestampEnvelopeMs = timestampDeltaMs(timestamps[0], timestamps[timestampQueryCount - 1]);
112	
113	        std::cout << PRINT_PREFIX << "GPU sort finished in " << gpuSortTime << "[ms]." << std::endl;
114	        std::cout << PRINT_PREFIX << "GPU timestamp radix passes sum: " << gpuTimestampSumMs << "[ms]." << std::endl;
115	        std::cout << PRINT_PREFIX << "GPU timestamp radix passes envelope: " << gpuTimestampEnvelopeMs << "[ms]." << std::endl;
116	        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_SUM_MS " << gpuTimestampSumMs << std::endl;
117	        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_ENVELOPE_MS " << gpuTimestampEnvelopeMs << std::endl;
118	
119	        // cpu sorting
120	        double cpuSortTime = sort(m_elementsIn);
121	        std::cout << PRINT_PREFIX << "CPU sort finished in " << cpuSortTime << "[ms]." << std::endl;
122	
123	        // verify result
124	        verify(m_elementsIn);
125	
126	        // clean up
127	        releaseBuffers();
128	        m_pass->release();
129	
130	        //        std::ofstream myfile;
131	        //        myfile.open("multiradixsort_block_" + std::to_string(m_numElements) + ".csv", std::ios_base::app);
132	        //        myfile << m_numElements << " " << NUM_BLOCKS_PER_WORKGROUP << " " << std::to_string(gpuSortTime) << " " << std::to_string(cpuSortTime) << std::endl;
133	    }
134	
135	    void MultiRadixSort::prepareBuffers() {
136	        generateRandomNumbers(m_elementsIn, m_numElements);
137	        //        printBuffer("elements_in", m_elementsIn, m_numElements);
138	        auto settings0 = Buffer::BufferSettings{.m_sizeBytes = getNumElementsBytes(), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer0"};
139	        m_buffers[0] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings0, m_elementsIn.data());
140	
141	        std::vector<SORT_TYPE> zeros;
142	        generateZeros(zeros, m_numElements);
143	        auto settings1 = Buffer::BufferSettings{.m_sizeBytes = getNumElementsBytes(), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer1"};
144	        m_buffers[1] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings1, zeros.data());
145	        auto settings2 = Buffer::BufferSettings{.m_sizeBytes = static_cast<uint32_t>(m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width * RADIX_SORT_BINS * sizeof(uint32_t)), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.histogramsBuffer"};
146	        m_buffers[2] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings2, zeros.data());
147	    }
148	
149	    void MultiRadixSort::verify(std::vector<SORT_TYPE> &reference) {
150	        std::vector<SORT_TYPE> data(m_numElements);
151	        m_buffers[0]->downloadWithStagingBuffer(data.data());
152	        //            printBuffer("elements_out", data, m_numElements);
153	        testSort(reference, data);
154	    }
155	
156	    void MultiRadixSort::printBuffer(const std::string &label, std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
157	        std::cout << label << ":" << std::endl;
158	        for (uint32_t i = 0; i < numElements; i++) {
159	            if (i > 0 && i % 16 == 0) {
160	                std::cout << std::endl;
161	            }
162	            std::cout << std::setfill(' ') << std::setw(9) << buffer[i] << " ";
163	        }
164	        std::cout << std::endl;
165	    }
166	
167	    void MultiRadixSort::releaseBuffers() {
168	        for (const auto &buffer: m_buffers) {
169	            buffer->release();
170	        }
171	    }
172	
173	    void MultiRadixSort::generateRandomNumbers(std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
174	        // https://en.cppreference.com/w/cpp/numeric/random/uniform_int_distribution
175	        std::random_device rd;
176	        std::mt19937 gen(rd());
177	#ifdef SORT_32BIT
178	        std::uniform_int_distribution<uint32_t> distrib(0, 0x0FFFFFFF);
179	#else
180	        std::uniform_int_distribution<uint64_t> distrib(0, 0x0FFFFFFFFFFF);
181	#endif
182	        for (int i = 0; i < numElements; i++) {
183	            buffer.push_back(distrib(gen));
184	        }
185	    }
186	
187	    void MultiRadixSort::generateZeros(std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
188	        for (int i = 0; i < numElements; i++) {
189	            buffer.push_back(0);
190	        }
191	    }
192	
193	    double MultiRadixSort::sort(std::vector<SORT_TYPE> &buffer) {
194	        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
195	        std::sort(buffer.begin(), buffer.end());
196	        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
197	        return (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));
198	    }
199	
200	    bool MultiRadixSort::testSort(std::vector<SORT_TYPE> &reference, std::vector<SORT_TYPE> &outBuffer) {
201	        if (reference.size() != outBuffer.size()) {
202	            std::cerr << PRINT_PREFIX << "reference.size() != outBuffer.size()" << std::endl;
203	            throw std::runtime_error("TEST FAILED.");
204	        }
205	        for (uint32_t i = 0; i < reference.size(); i++) {
206	            if (reference[i] != outBuffer[i]) {
207	                std::cerr << PRINT_PREFIX << reference[i] << " = reference[" << i << "] != outBuffer[" << i << "] = " << outBuffer[i] << std::endl;
208	                throw std::runtime_error("TEST FAILED.");
209	            }
210	        }
211	        std::cout << PRINT_PREFIX << "Test passed." << std::endl;
212	        return true;
213	    }
214	} // namespace engine

