1	#pragma once
2	
3	#include "Pass.h"
4	
5	namespace engine {
6	    class ComputePass : public Pass {
7	    public:
8	        explicit ComputePass(GPUContext *gpuContext) : Pass(gpuContext) {
9	        }
10	
11	        void create() override {
12	            Pass::create();
13	            m_workGroupCounts.resize(m_shaders.size());
14	        }
15	
16	        void setGlobalInvocationSize(uint32_t stageIndex, uint32_t width, uint32_t height, uint32_t depth) {
17	            VkExtent3D workGroupSize = m_shaders[stageIndex]->getWorkGroupSize();
18	            VkExtent3D dispatchSize = getDispatchSize(width, height, depth, workGroupSize);
19	            m_workGroupCounts[stageIndex] = {dispatchSize.width, dispatchSize.height, dispatchSize.depth};
20	            //            std::cout << "m_workGroupSize[" << stageIndex << "]=(" << workGroupSize.width << "," << workGroupSize.height << "," << workGroupSize.depth << ")" << std::endl;
21	            //            std::cout << "m_workGroupCount[" << stageIndex << "]=(" << dispatchSize.width << "," << dispatchSize.height << "," << dispatchSize.depth << ")" << std::endl;
22	        }
23	
24	        static VkExtent3D getDispatchSize(uint32_t width, uint32_t height, uint32_t depth, VkExtent3D workGroupSize) {
25	            uint32_t x = (width + workGroupSize.width - 1) / workGroupSize.width;
26	            uint32_t y = (height + workGroupSize.height - 1) / workGroupSize.height;
27	            uint32_t z = (depth + workGroupSize.depth - 1) / workGroupSize.depth;
28	            return {x, y, z};
29	        }
30	
31	        VkSemaphore execute(VkSemaphore awaitBeforeExecution) override {
32	            return executeInternal(awaitBeforeExecution, VK_NULL_HANDLE, 0, 0);
33	        }
34	
35	        VkSemaphore execute(VkSemaphore awaitBeforeExecution, VkQueryPool timestampQueryPool, uint32_t timestampStartQuery, uint32_t timestampEndQuery) {
36	            return executeInternal(awaitBeforeExecution, timestampQueryPool, timestampStartQuery, timestampEndQuery);
37	        }
38	
39	        [[nodiscard]] VkExtent3D getWorkGroupCount(uint32_t stageIndex) {
40	            return m_workGroupCounts[stageIndex];
41	        }
42	
43	    protected:
44	        uint32_t findQueueFamilyIndex() override {
45	            Queues::QueueFamilyIndices queueFamilyIndices = m_gpuContext->m_queues->findQueueFamilies(m_gpuContext->m_physicalDevice);
46	            return queueFamilyIndices.computeFamily.value();
47	        }
48	
49	        void createPipelines() override {
50	            for (uint32_t stageIndex = 0; stageIndex < m_shaders.size(); stageIndex++) {
51	                const auto &shader = m_shaders[stageIndex];
52	                VkPipelineShaderStageCreateInfo shaderStage = shader->generateShaderStageCreateInfo(VK_SHADER_STAGE_COMPUTE_BIT);
53	
54	                VkComputePipelineCreateInfo pipelineInfo{};
55	                pipelineInfo.sType = VK_STRUCTURE_TYPE_COMPUTE_PIPELINE_CREATE_INFO;
56	                pipelineInfo.layout = m_pipelineLayouts[stageIndex];
57	                pipelineInfo.stage = shaderStage;
58	
59	                m_pipelines.emplace_back();
60	                if (vkCreateComputePipelines(m_gpuContext->m_device, VK_NULL_HANDLE, 1, &pipelineInfo, nullptr, &m_pipelines[m_pipelines.size() - 1]) != VK_SUCCESS) {
61	                    throw std::runtime_error("Failed to create compute pipeline!");
62	                }
63	            }
64	        }
65	
66	        virtual void recordCommands(VkCommandBuffer commandBuffer) {
67	            recordCommandComputeShaderExecution(commandBuffer, 0);
68	        }
69	
70	        void recordCommandComputeShaderExecution(VkCommandBuffer commandBuffer, uint32_t stageIndex) {
71	            vkCmdBindPipeline(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, m_pipelines[stageIndex]);
72	
73	            std::vector<VkDescriptorSet> descriptorSets;
74	            getDescriptorSets(descriptorSets);
75	            vkCmdBindDescriptorSets(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, m_pipelineLayouts[stageIndex], 0, descriptorSets.size(), descriptorSets.data(), 0, nullptr);
76	
77	            vkCmdDispatch(commandBuffer, m_workGroupCounts[stageIndex].width, m_workGroupCounts[stageIndex].height, m_workGroupCounts[stageIndex].depth);
78	        }
79	
80	    private:
81	        std::vector<VkExtent3D> m_workGroupCounts;
82	
83	        VkSemaphore executeInternal(VkSemaphore awaitBeforeExecution, VkQueryPool timestampQueryPool, uint32_t timestampStartQuery, uint32_t timestampEndQuery) {
84	            vkWaitForFences(m_gpuContext->m_device, 1, &m_fences[m_gpuContext->getActiveIndex()], VK_TRUE, UINT64_MAX); // waiting for the previous frame to finish, blocks the CPU
85	            vkResetFences(m_gpuContext->m_device, 1, &m_fences[m_gpuContext->getActiveIndex()]);
86	
87	            vkResetCommandBuffer(m_commandBuffers[m_gpuContext->getActiveIndex()], 0);
88	            fillCommandBuffer(m_commandBuffers[m_gpuContext->getActiveIndex()], timestampQueryPool, timestampStartQuery, timestampEndQuery);
89	
90	            VkSubmitInfo submitInfo{};
91	            submitInfo.sType = VK_STRUCTURE_TYPE_SUBMIT_INFO;
92	            if (awaitBeforeExecution != VK_NULL_HANDLE) {
93	                VkPipelineStageFlags waitStages[] = {VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT};
94	                submitInfo.waitSemaphoreCount = 1;
95	                submitInfo.pWaitSemaphores = &awaitBeforeExecution; // wait on dependent operation
96	                submitInfo.pWaitDstStageMask = waitStages;
97	            }
98	            submitInfo.commandBufferCount = 1;
99	            submitInfo.pCommandBuffers = &m_commandBuffers[m_gpuContext->getActiveIndex()];
100	            submitInfo.signalSemaphoreCount = 1;
101	            submitInfo.pSignalSemaphores = &m_signalSemaphores[m_gpuContext->getActiveIndex()]; // is signaled when the command buffer has finished execution
102	
103	            if (vkQueueSubmit(m_gpuContext->m_queues->getQueue(Queues::COMPUTE), 1, &submitInfo, m_fences[m_gpuContext->getActiveIndex()]) != VK_SUCCESS) { // signal fence after the command buffer finished execution
104	                throw std::runtime_error("Failed to submit compute command buffer!");
105	            }
106	
107	            return m_signalSemaphores[m_gpuContext->getActiveIndex()];
108	        }
109	
110	        void fillCommandBuffer(VkCommandBuffer commandBuffer, VkQueryPool timestampQueryPool, uint32_t timestampStartQuery, uint32_t timestampEndQuery) {
111	            // fill command buffer
112	            VkCommandBufferBeginInfo beginInfo{};
113	            beginInfo.sType = VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO;
114	
115	            if (vkBeginCommandBuffer(commandBuffer, &beginInfo) != VK_SUCCESS) {
116	                throw std::runtime_error("failed to begin recording command buffer!");
117	            }
118	
119	            if (timestampQueryPool != VK_NULL_HANDLE) {
120	                vkCmdWriteTimestamp(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, timestampQueryPool, timestampStartQuery);
121	            }
122	
123	            recordCommands(commandBuffer);
124	
