189	        void createDescriptorSetLayout() {
190	            // retrieve information using SPIRV-reflect
191	            for (const auto &shader: m_shaders) {                                     // for every shader
192	                for (const auto &layoutData: *shader->getDescriptorSetLayoutData()) { // retrieve all sets
193	                    uint32_t setId = layoutData.first;
194	                    const Shader::DescriptorSetLayoutData &layout = layoutData.second;
195	
196	                    if (m_descriptorSetToIndex.contains(setId)) {
197	                        // merge with existing set
198	                        uint32_t index = m_descriptorSetToIndex[setId];
199	                        auto &mergedLayoutData = m_descriptorSetLayoutData[index];
200	                        assert(setId == mergedLayoutData.set_number);
201	                        mergedLayoutData.bindings.insert(mergedLayoutData.bindings.end(), layout.bindings.begin(), layout.bindings.end());
202	                        //                        for (auto &binding : layout.bindings) {
203	                        //
204	                        //                        }
205	                    } else {
206	                        // insert new set
207	                        uint32_t index = m_descriptorSetLayoutData.size();
208	                        m_descriptorSetToIndex[setId] = index;
209	                        Shader::DescriptorSetLayoutData newLayoutData{.set_number = setId, .bindings = layout.bindings};
210	                        m_descriptorSetLayoutData.push_back(newLayoutData);
211	                    }
212	                }
213	
214	                for (const auto &[bindingId, uniforms]: *shader->getUniforms()) {
215	                    for (const auto &uniform: uniforms) {
216	                        m_uniforms[uniform->getSet()][uniform->getBinding()] = uniform;
217	                    }
218	                }
219	            }
220	
221	            for (auto &layoutData: m_descriptorSetLayoutData) {
222	                layoutData.create_info.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_LAYOUT_CREATE_INFO;
223	                layoutData.create_info.bindingCount = layoutData.bindings.size();
224	                layoutData.create_info.pBindings = layoutData.bindings.data();
225	
226	                layoutData.generateBindingToIndexMap();
227	            }
228	
229	            m_descriptorSetLayouts.resize(m_descriptorSetLayoutData.size());
230	            for (auto &layoutData: m_descriptorSetLayoutData) {
231	                uint32_t index = m_descriptorSetToIndex[layoutData.set_number];
232	                if (vkCreateDescriptorSetLayout(m_gpuContext->m_device, &layoutData.create_info, nullptr, &m_descriptorSetLayouts[index]) != VK_SUCCESS) {
233	                    throw std::runtime_error("Failed to create descriptor set layout!");
234	                }
235	            }
236	        }
237	
238	        void createDescriptorPool() {
239	            // retrieve information using SPIRV-reflect
240	            std::map<VkDescriptorType, uint32_t> descriptorCounts;
241	            for (const auto &layoutData: m_descriptorSetLayoutData) {
242	                for (const auto &binding: layoutData.bindings) {
243	                    if (descriptorCounts.contains(binding.descriptorType)) {
244	                        descriptorCounts[binding.descriptorType] += binding.descriptorCount;
245	                    } else {
246	                        descriptorCounts[binding.descriptorType] = binding.descriptorCount;
247	                    }
248	                }
249	            }
250	
251	            std::vector<VkDescriptorPoolSize> poolSizes;
252	            for (const auto &[descriptorType, count]: descriptorCounts) {
253	                poolSizes.push_back({descriptorType, count * m_gpuContext->getMultiBufferedCount()});
254	            }
255	
256	            VkDescriptorPoolCreateInfo poolInfo{};
257	            poolInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_POOL_CREATE_INFO;
258	            poolInfo.poolSizeCount = static_cast<uint32_t>(poolSizes.size());
259	            poolInfo.pPoolSizes = poolSizes.data();
260	            poolInfo.maxSets = m_gpuContext->getMultiBufferedCount() * m_descriptorSetLayouts.size();
261	
262	            if (vkCreateDescriptorPool(m_gpuContext->m_device, &poolInfo, nullptr, &m_descriptorPool) != VK_SUCCESS) {
263	                throw std::runtime_error("Failed to create descriptor pool!");
264	            }
265	        }
266	
267	        void createDescriptorSets() {
268	            // allocate descriptor sets (valid values will be set later)
269	            m_descriptorSets.resize(m_gpuContext->getMultiBufferedCount());
270	            for (uint32_t i = 0; i < m_gpuContext->getMultiBufferedCount(); i++) {
271	                VkDescriptorSetAllocateInfo allocInfo{};
272	                allocInfo.sType = VK_STRUCTURE_TYPE_DESCRIPTOR_SET_ALLOCATE_INFO;
273	                allocInfo.descriptorPool = m_descriptorPool;
274	                allocInfo.descriptorSetCount = m_descriptorSetLayouts.size();
275	                allocInfo.pSetLayouts = m_descriptorSetLayouts.data();
276	
277	                m_descriptorSets[i].resize(m_descriptorSetLayouts.size());
278	                if (vkAllocateDescriptorSets(m_gpuContext->m_device, &allocInfo, m_descriptorSets[i].data()) != VK_SUCCESS) {
279	                    throw std::runtime_error("Failed to allocate descriptor sets!");
280	                }
281	            }
282	        }
283	
284	        void createSyncObjects() {
285	            m_signalSemaphores.resize(m_gpuContext->getMultiBufferedCount());
286	            m_fences.resize(m_gpuContext->getMultiBufferedCount());
287	
288	            VkSemaphoreCreateInfo semaphoreInfo{};
289	            semaphoreInfo.sType = VK_STRUCTURE_TYPE_SEMAPHORE_CREATE_INFO;
290	
291	            VkFenceCreateInfo fenceInfo{};
292	            fenceInfo.sType = VK_STRUCTURE_TYPE_FENCE_CREATE_INFO;
293	            fenceInfo.flags = VK_FENCE_CREATE_SIGNALED_BIT; // create in signaled state, such that the first vkWaitForFences(..) call immediately returns (there is no previous frame to wait for when starting the application)
294	
295	            for (size_t i = 0; i < m_gpuContext->getMultiBufferedCount(); i++) {
296	                if (vkCreateSemaphore(m_gpuContext->m_device, &semaphoreInfo, nullptr, &m_signalSemaphores[i]) != VK_SUCCESS ||
297	                    vkCreateFence(m_gpuContext->m_device, &fenceInfo, nullptr, &m_fences[i]) != VK_SUCCESS) {
298	                    throw std::runtime_error("Failed to create synchronization objects for a frame!");
299	                }
300	            }
301	        }
302	
303	        void releaseSyncObjects() {
304	            for (size_t i = 0; i < m_gpuContext->getMultiBufferedCount(); i++) {
305	                vkDestroySemaphore(m_gpuContext->m_device, m_signalSemaphores[i], nullptr);
306	                vkDestroyFence(m_gpuContext->m_device, m_fences[i], nullptr);
307	            }
308	        }
309	
310	        void createUniforms() {
311	            for (const auto &[set, uniforms]: m_uniforms) {
312	                for (const auto &[binding, uniform]: uniforms) {
313	                    uniform->create();
314	                    setUniform(uniform.get());
315	                }
316	            }
317	        }
318	
319	        void releaseUniforms() {
320	            for (const auto &[set, uniforms]: m_uniforms) {
321	                for (const auto &[binding, uniform]: uniforms) {
322	                    uniform->release();
323	                }
324	            }
325	        }
326	
327	        void setUniform(Uniform *uniform) {
328	            uint32_t setIdx = m_descriptorSetToIndex[uniform->getSet()];
329	
330	            Shader::DescriptorSetLayoutData &layout = m_descriptorSetLayoutData[setIdx];
331	            const auto &bindingLayout = layout.bindings[layout.bindingToIndex[uniform->getBinding()]];
332	
333	            assert(uniform->getSet() == layout.set_number);
334	            assert(uniform->getBinding() == bindingLayout.binding);
335	
336	            VkWriteDescriptorSet writeDescriptorSet{};
337	            writeDescriptorSet.sType = VK_STRUCTURE_TYPE_WRITE_DESCRIPTOR_SET;
338	            writeDescriptorSet.dstBinding = uniform->getBinding();
339	            writeDescriptorSet.dstArrayElement = 0;
340	            writeDescriptorSet.descriptorType = bindingLayout.descriptorType;
341	            writeDescriptorSet.descriptorCount = 1;
342	
343	            for (uint32_t i = 0; i < m_gpuContext->getMultiBufferedCount(); i++) {
344	                VkDescriptorBufferInfo bufferInfo{};
345	                uniform->generateBufferInfo(&bufferInfo, i);
346	
347	                writeDescriptorSet.dstSet = m_descriptorSets[i][setIdx];
348	                writeDescriptorSet.pBufferInfo = &bufferInfo;
349	                vkUpdateDescriptorSets(m_gpuContext->m_device, 1, &writeDescriptorSet, 0, nullptr);
350	            }
351	        }
352	    };
353	} // namespace engine

