 17	        if (!m_initialized) {
 18	            throw std::runtime_error("MultiRadixSort::init() must be called before execute()");
 19	        }
 20	        m_numElements = numElements;
 21	
 22	        const uint32_t NUM_BLOCKS_PER_WORKGROUP = 32;
 23	        uint32_t globalInvocationSize = m_numElements / NUM_BLOCKS_PER_WORKGROUP;
 24	        uint32_t remainder = m_numElements % NUM_BLOCKS_PER_WORKGROUP;
 25	        globalInvocationSize += remainder > 0 ? 1 : 0;
 26	        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, globalInvocationSize, 1, 1);
 27	        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT, globalInvocationSize, 1, 1);
 28	
 29	        // push constants
 30	        const uint32_t NUM_WORKGROUPS = m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width;
 31	        assert(NUM_WORKGROUPS == m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT).width);
 32	        m_pass->m_pushConstantsHistogram.g_num_elements = m_numElements;
 33	        m_pass->m_pushConstantsHistogram.g_num_workgroups = NUM_WORKGROUPS;
 34	        m_pass->m_pushConstantsHistogram.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
 35	        m_pass->m_pushConstants.g_num_elements = m_numElements;
 36	        m_pass->m_pushConstants.g_num_workgroups = NUM_WORKGROUPS;
 37	        m_pass->m_pushConstants.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
 38	
 39	        // buffers
 40	        prepareBuffers();
 41	        std::cout << PRINT_PREFIX << "Sorting " << m_numElements << " " << (sizeof(m_elementsIn[0]) * 8) << "bit numbers." << std::endl;
 42	
 43	        // set storage buffers
 44	        uint32_t activeIndex = m_gpuContext->getActiveIndex();
 45	
 46	        // m_buffer0
 47	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[0].get()); // iteration 0 and 2 (0,0)
 48	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[0].get());            // iteration 0 and 2 (1,0)
 49	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[0].get());  // iteration 1 and 3 (1,1)
 50	
 51	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[1].get()); // iteration 1 and 3 (0,0)
 52	        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[1].get());                      // iteration 0 and 2 (1,1)
 53	        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[1].get());            // iteration 1 and 3 (1,0)
 54	
 55	        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 1, m_buffers[2].get());
 56	        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT, 2, m_buffers[2].get());
 57	
 58	        // execute pass
 59	        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
 60	        VkSemaphore awaitBeforeExecution = VK_NULL_HANDLE;
 61	#ifdef SORT_32BIT
 62	        const uint32_t NUM_ITERATIONS = 4;
 63	#else
 64	        const uint32_t NUM_ITERATIONS = 8;
 65	#endif
 66	        if (m_gpuContext->m_timestampPeriod <= 0.0f || m_gpuContext->m_computeTimestampValidBits == 0) {
 67	            throw std::runtime_error("Compute queue does not support valid timestamp queries!");
 68	        }
 69	
 70	        const uint32_t TIMESTAMP_QUERIES_PER_ITERATION = 2;
 71	        const uint32_t timestampQueryCount = NUM_ITERATIONS * TIMESTAMP_QUERIES_PER_ITERATION;
 72	        VkQueryPoolCreateInfo queryPoolInfo{};
 73	        queryPoolInfo.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO;
 74	        queryPoolInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
 75	        queryPoolInfo.queryCount = timestampQueryCount;
 76	
 77	        struct QueryPoolGuard {
 78	            VkDevice device = VK_NULL_HANDLE;
 79	            VkQueryPool pool = VK_NULL_HANDLE;
 80	            ~QueryPoolGuard() {
 81	                if (pool != VK_NULL_HANDLE) vkDestroyQueryPool(device, pool, nullptr);
 82	            }
 83	        } timestampQueries{m_gpuContext->m_device};
 84	
 85	        if (vkCreateQueryPool(m_gpuContext->m_device, &queryPoolInfo, nullptr, &timestampQueries.pool) != VK_SUCCESS) {
 86	            throw std::runtime_error("Failed to create timestamp query pool!");
 87	        }
 88	        vkResetQueryPool(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount);
 89	
 90	        for (uint32_t i = 0; i < NUM_ITERATIONS; i++) {
 91	            m_pass->m_pushConstantsHistogram.g_shift = 8 * i;
 92	            m_pass->m_pushConstants.g_shift = 8 * i;
 93	            const uint32_t queryBase = i * TIMESTAMP_QUERIES_PER_ITERATION;
 94	            awaitBeforeExecution = m_pass->execute(awaitBeforeExecution, timestampQueries.pool, queryBase, queryBase + 1);
 95	            m_gpuContext->incrementActiveIndex();
 96	        }
 97	        vkQueueWaitIdle(m_gpuContext->m_queues->getQueue(Queues::COMPUTE));
 98	        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
 99	        double gpuSortTime = (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));
100	
101	        std::vector<uint64_t> timestamps(timestampQueryCount);
102	        if (vkGetQueryPoolResults(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount, timestamps.size() * sizeof(uint64_t), timestamps.data(), sizeof(uint64_t), VK_QUERY_RESULT_64_BIT | VK_QUERY_RESULT_WAIT_BIT) != VK_SUCCESS) {
103	            throw std::runtime_error("Failed to read timestamp query results!");
104	        }
105	
106	        const uint64_t timestampMask = m_gpuContext->m_computeTimestampValidBits == 64 ? ~0ull : ((1ull << m_gpuContext->m_computeTimestampValidBits) - 1ull);
107	        const auto timestampDeltaMs = [&](uint64_t start, uint64_t end) {
108	            start &= timestampMask;
109	            end &= timestampMask;
110	            const uint64_t delta = end >= start ? end - start : timestampMask - start + end + 1;
111	            return static_cast<double>(delta) * m_gpuContext->m_timestampPeriod / 1000000.0;
112	        };
113	
114	        double gpuTimestampSumMs = 0.0;
115	        for (uint32_t i = 0; i < NUM_ITERATIONS; ++i) {
116	            const uint64_t start = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION];
117	            const uint64_t end = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION + 1];
118	            gpuTimestampSumMs += timestampDeltaMs(start, end);
119	        }
120	        const double gpuTimestampEnvelopeMs = timestampDeltaMs(timestamps[0], timestamps[timestampQueryCount - 1]);
121	
122	        std::cout << PRINT_PREFIX << "GPU sort finished in " << gpuSortTime << "[ms]." << std::endl;
123	        std::cout << PRINT_PREFIX << "GPU timestamp radix passes sum: " << gpuTimestampSumMs << "[ms]." << std::endl;
124	        std::cout << PRINT_PREFIX << "GPU timestamp radix passes envelope: " << gpuTimestampEnvelopeMs << "[ms]." << std::endl;
125	        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_SUM_MS " << gpuTimestampSumMs << std::endl;
126	        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_ENVELOPE_MS " << gpuTimestampEnvelopeMs << std::endl;
127	
128	        // cpu sorting
129	        double cpuSortTime = sort(m_elementsIn);
130	        std::cout << PRINT_PREFIX << "CPU sort finished in " << cpuSortTime << "[ms]." << std::endl;
131	
132	        // verify result
133	        verify(m_elementsIn);
134	
135	        // release buffers for this size (pass is reused)
136	        releaseBuffers();
137	    }
