10	#ifdef RESOURCE_DIRECTORY_PATH
11	    engine::Paths::m_resourceDirectoryPath = RESOURCE_DIRECTORY_PATH;
12	#endif
13	
14	    // parse sizes from argv
15	    std::vector<uint32_t> sizes;
16	    if (argc >= 2) {
17	        for (int i = 1; i < argc; i++) {
18	            sizes.push_back(static_cast<uint32_t>(std::strtoul(argv[i], nullptr, 10)));
19	        }
20	    } else {
21	        sizes = {1024, 2048, 4096, 8192, 16384, 32768, 65536, 131072, 262144, 524288, 1048576};
22	    }
