              << "ms downsweep=" << toMs(median(downsweep_times))
              << "ms finalize=" << toMs(median(finalize_times)) << "ms" << std::endl;
  }

  return Row{n, sort, toMs(gpu_med), toMs(cpu_med),
             toGItemsS(n, gpu_med), toGItemsS(n, cpu_med)};
}

