#version 450
#extension GL_KHR_shader_subgroup_basic : require
#extension GL_KHR_shader_subgroup_arithmetic : require
#extension GL_KHR_shader_subgroup_ballot : require

const uint RADIX = 256;
const uint WORKGROUP_SIZE = 256;
const uint PARTITION_DIVISION = 8;
const uint PARTITION_SIZE = PARTITION_DIVISION * WORKGROUP_SIZE;

layout(local_size_x = WORKGROUP_SIZE) in;

layout(push_constant) uniform PushConstants {
    int pass;
    uint maxElementCount;
} pc;

layout(set = 0, binding = 0, std430) readonly buffer ElementCounts {
    uint elementCounts[];
};

layout(set = 0, binding = 1, std430) buffer GlobalHistogram {
    uint globalHistogram[];
};

layout(set = 0, binding = 2, std430) buffer PartitionHistogram {
    uint partitionHistogram[];
};

layout(set = 0, binding = 3, std430) readonly buffer KeysIn {
    uint keysIn[];
};

layout(set = 0, binding = 4, std430) buffer KeysOut {
    uint keysOut[];
};

#ifdef KEY_VALUE
layout(set = 0, binding = 5, std430) readonly buffer ValuesIn {
    uint valuesIn[];
};

layout(set = 0, binding = 6, std430) buffer ValuesOut {
    uint valuesOut[];
};
#endif

shared uint localHistogram[PARTITION_SIZE];
shared uint localHistogramSum[RADIX];
shared uint subgroupSums[8];

uvec4 getExclusiveWaveMask(uint laneIndex) {
    uvec4 mask = uvec4(0);
    for (int i = 0; i < 4; ++i) {
        if (laneIndex < 32) {
            mask[i] = (1u << laneIndex) - 1u;
            laneIndex = 0;
        } else {
            mask[i] = 0xffffffffu;
            laneIndex -= 32;
        }
    }
    return mask;
}

uint getBitCount(uvec4 value) {
    uvec4 result = bitCount(value);
    return result.x + result.y + result.z + result.w;
}

void main() {
    uint elementCount = min(elementCounts[0], pc.maxElementCount);

    uint laneIndex = gl_SubgroupInvocationID;
    uint laneCount = gl_SubgroupSize;
    uint waveIndex = gl_LocalInvocationIndex / laneCount;
    uint waveCount = WORKGROUP_SIZE / laneCount;
    uint index = waveIndex * laneCount + laneIndex;

    uvec4 waveMask = getExclusiveWaveMask(laneIndex);

    uint partitionIndex = gl_WorkGroupID.x;
    uint partitionStart = partitionIndex * PARTITION_SIZE;

    // This condition is uniform across the workgroup, keeping every barrier converged.
    if (partitionStart < elementCount) {
        for (uint i = index; i < RADIX * waveCount; i += WORKGROUP_SIZE) {
            localHistogram[i] = 0;
        }
        barrier();

        uint localKeys[PARTITION_DIVISION];
        uint localRadix[PARTITION_DIVISION];
        uint localOffsets[PARTITION_DIVISION];
        uint waveHistogram[PARTITION_DIVISION];
#ifdef KEY_VALUE
        uint localValues[PARTITION_DIVISION];
#endif

        for (uint i = 0; i < PARTITION_DIVISION; ++i) {
            uint keyIndex = partitionStart + (PARTITION_DIVISION * laneCount) * waveIndex +
                            i * laneCount + laneIndex;
            uint key = keyIndex < elementCount ? keysIn[keyIndex] : 0xffffffffu;
            localKeys[i] = key;
#ifdef KEY_VALUE
            localValues[i] = keyIndex < elementCount ? valuesIn[keyIndex] : 0;
#endif

            uint radix = bitfieldExtract(key, pc.pass * 8, 8);
            localRadix[i] = radix;

            uvec4 mask = subgroupBallot(true);
            for (uint bit = 0; bit < 8; ++bit) {
                uint digit = (radix >> bit) & 1u;
                uvec4 ballot = subgroupBallot(digit == 1u);
                mask &= uvec4(digit - 1u) ^ ballot;
            }

            uint waveOffset = getBitCount(waveMask & mask);
            uint radixCount = getBitCount(mask);
            if (waveOffset == 0) {
                atomicAdd(localHistogram[waveIndex * RADIX + radix], radixCount);
                waveHistogram[i] = radixCount;
            } else {
                waveHistogram[i] = 0;
            }
            localOffsets[i] = waveOffset;
        }
        barrier();

        uint radixTotal = 0;
        for (uint wave = 0; wave < waveCount; ++wave) {
            uint histogramIndex = wave * RADIX + index;
            uint count = localHistogram[histogramIndex];
            localHistogram[histogramIndex] = radixTotal;
            radixTotal += count;
        }

        uint subgroupCount = subgroupAdd(radixTotal);
        localHistogramSum[index] = subgroupExclusiveAdd(radixTotal);
        if (laneIndex == 0) {
            subgroupSums[waveIndex] = subgroupCount;
        }
        barrier();

        uint subgroupPrefix = 0;
        for (uint subgroup = 0; subgroup < waveIndex; ++subgroup) {
            subgroupPrefix += subgroupSums[subgroup];
        }
        localHistogramSum[index] += subgroupPrefix;
        barrier();

        for (uint i = 0; i < PARTITION_DIVISION; ++i) {
            uint radix = localRadix[i];
            localOffsets[i] += localHistogramSum[radix] +
                               localHistogram[waveIndex * RADIX + radix];
            subgroupBarrier();
            if (waveHistogram[i] > 0) {
                atomicAdd(localHistogram[waveIndex * RADIX + radix], waveHistogram[i]);
            }
            subgroupBarrier();
        }
        barrier();

        for (uint i = index; i < RADIX; i += WORKGROUP_SIZE) {
            localHistogramSum[i] = globalHistogram[RADIX * uint(pc.pass) + i] +
                                   partitionHistogram[RADIX * partitionIndex + i] -
                                   localHistogramSum[i];
        }
        barrier();

#ifdef KEY_VALUE
        for (uint i = 0; i < PARTITION_DIVISION; ++i) {
            localHistogram[localOffsets[i]] = localKeys[i];
        }
        barrier();

        for (uint i = index; i < PARTITION_SIZE; i += WORKGROUP_SIZE) {
            uint key = localHistogram[i];
            uint radix = bitfieldExtract(key, pc.pass * 8, 8);
            uint dstOffset = localHistogramSum[radix] + i;
            if (dstOffset < elementCount) {
                keysOut[dstOffset] = key;
            }
            localKeys[i / WORKGROUP_SIZE] = dstOffset;
        }

        barrier();

        for (uint i = 0; i < PARTITION_DIVISION; ++i) {
            localHistogram[localOffsets[i]] = localValues[i];
        }
        barrier();

        for (uint i = index; i < PARTITION_SIZE; i += WORKGROUP_SIZE) {
            uint value = localHistogram[i];
            uint dstOffset = localKeys[i / WORKGROUP_SIZE];
            if (dstOffset < elementCount) {
                valuesOut[dstOffset] = value;
            }
        }
#else
        for (uint i = 0; i < PARTITION_DIVISION; ++i) {
            localHistogram[localOffsets[i]] = localKeys[i];
        }
        barrier();

        for (uint i = index; i < PARTITION_SIZE; i += WORKGROUP_SIZE) {
            uint key = localHistogram[i];
            uint radix = bitfieldExtract(key, pc.pass * 8, 8);
            uint dstOffset = localHistogramSum[radix] + i;
            if (dstOffset < elementCount) {
                keysOut[dstOffset] = key;
            }
        }
#endif
    }
}

#include "MultiRadixSort.h"

namespace engine {

    void MultiRadixSort::init(GPUContext *gpuContext) {
        m_gpuContext = gpuContext;

        // compute pass — create once, reuse across all N
        m_pass = std::make_shared<MultiRadixSortPass>(gpuContext);
        m_pass->create();

        m_initialized = true;
        std::cout << PRINT_PREFIX << "Pipeline created (reused across all sizes)." << std::endl;
    }

    double MultiRadixSort::execute(uint32_t numElements) {
        if (!m_initialized) {
            throw std::runtime_error("MultiRadixSort::init() must be called before execute()");
        }
        m_numElements = numElements;

        const uint32_t NUM_BLOCKS_PER_WORKGROUP = 32;
        uint32_t globalInvocationSize = m_numElements / NUM_BLOCKS_PER_WORKGROUP;
        uint32_t remainder = m_numElements % NUM_BLOCKS_PER_WORKGROUP;
        globalInvocationSize += remainder > 0 ? 1 : 0;
        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, globalInvocationSize, 1, 1);
        m_pass->setGlobalInvocationSize(MultiRadixSortPass::RADIX_SORT, globalInvocationSize, 1, 1);

        // push constants
        const uint32_t NUM_WORKGROUPS = m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width;
        assert(NUM_WORKGROUPS == m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT).width);
        m_pass->m_pushConstantsHistogram.g_num_elements = m_numElements;
        m_pass->m_pushConstantsHistogram.g_num_workgroups = NUM_WORKGROUPS;
        m_pass->m_pushConstantsHistogram.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;
        m_pass->m_pushConstants.g_num_elements = m_numElements;
        m_pass->m_pushConstants.g_num_workgroups = NUM_WORKGROUPS;
        m_pass->m_pushConstants.g_num_blocks_per_workgroup = NUM_BLOCKS_PER_WORKGROUP;

        // buffers
        prepareBuffers();
        std::cout << PRINT_PREFIX << "Sorting " << m_numElements << " " << (sizeof(m_elementsIn[0]) * 8) << "bit numbers." << std::endl;

        // set storage buffers
        uint32_t activeIndex = m_gpuContext->getActiveIndex();

        // m_buffer0
        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[0].get()); // iteration 0 and 2 (0,0)
        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[0].get());            // iteration 0 and 2 (1,0)
        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[0].get());  // iteration 1 and 3 (1,1)

        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 0, m_buffers[1].get()); // iteration 1 and 3 (0,0)
        m_pass->setStorageBuffer(activeIndex, MultiRadixSortPass::RADIX_SORT, 1, m_buffers[1].get());                      // iteration 0 and 2 (1,1)
        m_pass->setStorageBuffer((activeIndex + 1) % 2, MultiRadixSortPass::RADIX_SORT, 0, m_buffers[1].get());            // iteration 1 and 3 (1,0)

        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS, 1, m_buffers[2].get());
        m_pass->setStorageBuffer(MultiRadixSortPass::RADIX_SORT, 2, m_buffers[2].get());

        // execute pass
        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
        VkSemaphore awaitBeforeExecution = VK_NULL_HANDLE;
#ifdef SORT_32BIT
        const uint32_t NUM_ITERATIONS = 4;
#else
        const uint32_t NUM_ITERATIONS = 8;
#endif
        if (m_gpuContext->m_timestampPeriod <= 0.0f || m_gpuContext->m_computeTimestampValidBits == 0) {
            throw std::runtime_error("Compute queue does not support valid timestamp queries!");
        }

        const uint32_t TIMESTAMP_QUERIES_PER_ITERATION = 2;
        const uint32_t timestampQueryCount = NUM_ITERATIONS * TIMESTAMP_QUERIES_PER_ITERATION;
        VkQueryPoolCreateInfo queryPoolInfo{};
        queryPoolInfo.sType = VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO;
        queryPoolInfo.queryType = VK_QUERY_TYPE_TIMESTAMP;
        queryPoolInfo.queryCount = timestampQueryCount;

        struct QueryPoolGuard {
            VkDevice device = VK_NULL_HANDLE;
            VkQueryPool pool = VK_NULL_HANDLE;
            ~QueryPoolGuard() {
                if (pool != VK_NULL_HANDLE) vkDestroyQueryPool(device, pool, nullptr);
            }
        } timestampQueries{m_gpuContext->m_device};

        if (vkCreateQueryPool(m_gpuContext->m_device, &queryPoolInfo, nullptr, &timestampQueries.pool) != VK_SUCCESS) {
            throw std::runtime_error("Failed to create timestamp query pool!");
        }
        vkResetQueryPool(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount);

        for (uint32_t i = 0; i < NUM_ITERATIONS; i++) {
            m_pass->m_pushConstantsHistogram.g_shift = 8 * i;
            m_pass->m_pushConstants.g_shift = 8 * i;
            const uint32_t queryBase = i * TIMESTAMP_QUERIES_PER_ITERATION;
            awaitBeforeExecution = m_pass->execute(awaitBeforeExecution, timestampQueries.pool, queryBase, queryBase + 1);
            m_gpuContext->incrementActiveIndex();
        }
        vkQueueWaitIdle(m_gpuContext->m_queues->getQueue(Queues::COMPUTE));
        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        double gpuSortTime = (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));

        std::vector<uint64_t> timestamps(timestampQueryCount);
        if (vkGetQueryPoolResults(m_gpuContext->m_device, timestampQueries.pool, 0, timestampQueryCount, timestamps.size() * sizeof(uint64_t), timestamps.data(), sizeof(uint64_t), VK_QUERY_RESULT_64_BIT | VK_QUERY_RESULT_WAIT_BIT) != VK_SUCCESS) {
            throw std::runtime_error("Failed to read timestamp query results!");
        }

        const uint64_t timestampMask = m_gpuContext->m_computeTimestampValidBits == 64 ? ~0ull : ((1ull << m_gpuContext->m_computeTimestampValidBits) - 1ull);
        const auto timestampDeltaMs = [&](uint64_t start, uint64_t end) {
            start &= timestampMask;
            end &= timestampMask;
            const uint64_t delta = end >= start ? end - start : timestampMask - start + end + 1;
            return static_cast<double>(delta) * m_gpuContext->m_timestampPeriod / 1000000.0;
        };

        double gpuTimestampSumMs = 0.0;
        for (uint32_t i = 0; i < NUM_ITERATIONS; ++i) {
            const uint64_t start = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION];
            const uint64_t end = timestamps[i * TIMESTAMP_QUERIES_PER_ITERATION + 1];
            gpuTimestampSumMs += timestampDeltaMs(start, end);
        }
        const double gpuTimestampEnvelopeMs = timestampDeltaMs(timestamps[0], timestamps[timestampQueryCount - 1]);

        std::cout << PRINT_PREFIX << "GPU sort finished in " << gpuSortTime << "[ms]." << std::endl;
        std::cout << PRINT_PREFIX << "GPU timestamp radix passes sum: " << gpuTimestampSumMs << "[ms]." << std::endl;
        std::cout << PRINT_PREFIX << "GPU timestamp radix passes envelope: " << gpuTimestampEnvelopeMs << "[ms]." << std::endl;
        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_SUM_MS " << gpuTimestampSumMs << std::endl;
        std::cout << PRINT_PREFIX << "GPU_TIMESTAMP_RADIX_PASSES_ENVELOPE_MS " << gpuTimestampEnvelopeMs << std::endl;

        // cpu sorting
        double cpuSortTime = sort(m_elementsIn);
        std::cout << PRINT_PREFIX << "CPU sort finished in " << cpuSortTime << "[ms]." << std::endl;

        // verify result
        verify(m_elementsIn);

        // release buffers for this size (pass is reused)
        releaseBuffers();

        return gpuTimestampEnvelopeMs;
    }

    void MultiRadixSort::cleanup() {
        if (m_initialized && m_pass) {
            m_pass->release();
            m_initialized = false;
            std::cout << PRINT_PREFIX << "Pipeline released." << std::endl;
        }
    }

    void MultiRadixSort::prepareBuffers() {
        m_elementsIn.clear();
        generateRandomNumbers(m_elementsIn, m_numElements);
        //        printBuffer("elements_in", m_elementsIn, m_numElements);
        auto settings0 = Buffer::BufferSettings{.m_sizeBytes = getNumElementsBytes(), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer0"};
        m_buffers[0] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings0, m_elementsIn.data());

        std::vector<SORT_TYPE> zeros;
        generateZeros(zeros, m_numElements);
        auto settings1 = Buffer::BufferSettings{.m_sizeBytes = getNumElementsBytes(), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.elementBuffer1"};
        m_buffers[1] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings1, zeros.data());
        auto settings2 = Buffer::BufferSettings{.m_sizeBytes = static_cast<uint32_t>(m_pass->getWorkGroupCount(MultiRadixSortPass::RADIX_SORT_HISTOGRAMS).width * RADIX_SORT_BINS * sizeof(uint32_t)), .m_bufferUsages = VK_BUFFER_USAGE_TRANSFER_DST_BIT | VK_BUFFER_USAGE_STORAGE_BUFFER_BIT, .m_memoryProperties = VK_MEMORY_PROPERTY_DEVICE_LOCAL_BIT, .m_name = "radixSort.histogramsBuffer"};
        m_buffers[2] = Buffer::fillDeviceWithStagingBuffer(m_gpuContext, settings2, zeros.data());
    }

    void MultiRadixSort::verify(std::vector<SORT_TYPE> &reference) {
        std::vector<SORT_TYPE> data(m_numElements);
        m_buffers[0]->downloadWithStagingBuffer(data.data());
        //            printBuffer("elements_out", data, m_numElements);
        testSort(reference, data);
    }

    void MultiRadixSort::printBuffer(const std::string &label, std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
        std::cout << label << ":" << std::endl;
        for (uint32_t i = 0; i < numElements; i++) {
            if (i > 0 && i % 16 == 0) {
                std::cout << std::endl;
            }
            std::cout << std::setfill(' ') << std::setw(9) << buffer[i] << " ";
        }
        std::cout << std::endl;
    }

    void MultiRadixSort::releaseBuffers() {
        for (const auto &buffer: m_buffers) {
            buffer->release();
        }
    }

    void MultiRadixSort::generateRandomNumbers(std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
        // https://en.cppreference.com/w/cpp/numeric/random/uniform_int_distribution
        std::random_device rd;
        std::mt19937 gen(rd());
#ifdef SORT_32BIT
        // Full 32-bit range to match vulkan_radix_sort benchmark
        std::uniform_int_distribution<uint32_t> distrib;
#else
        std::uniform_int_distribution<uint64_t> distrib;
#endif
        for (int i = 0; i < numElements; i++) {
            buffer.push_back(distrib(gen));
        }
    }

    void MultiRadixSort::generateZeros(std::vector<SORT_TYPE> &buffer, uint32_t numElements) {
        for (int i = 0; i < numElements; i++) {
            buffer.push_back(0);
        }
    }

    double MultiRadixSort::sort(std::vector<SORT_TYPE> &buffer) {
        std::chrono::steady_clock::time_point begin = std::chrono::steady_clock::now();
        std::sort(buffer.begin(), buffer.end());
        std::chrono::steady_clock::time_point end = std::chrono::steady_clock::now();
        return (static_cast<double>(std::chrono::duration_cast<std::chrono::microseconds>(end - begin).count()) * std::pow(10, -3));
    }

    bool MultiRadixSort::testSort(std::vector<SORT_TYPE> &reference, std::vector<SORT_TYPE> &outBuffer) {
        if (reference.size() != outBuffer.size()) {
            std::cerr << PRINT_PREFIX << "reference.size() != outBuffer.size()" << std::endl;
            throw std::runtime_error("TEST FAILED.");
        }
        for (uint32_t i = 0; i < reference.size(); i++) {
            if (reference[i] != outBuffer[i]) {
                std::cerr << PRINT_PREFIX << reference[i] << " = reference[" << i << "] != outBuffer[" << i << "] = " << outBuffer[i] << std::endl;
                throw std::runtime_error("TEST FAILED.");
            }
        }
        std::cout << PRINT_PREFIX << "Test passed." << std::endl;
        return true;
    }
