51	    std::vector<uint32_t> sizes;
52	    std::stringstream ss(argv[3]);
53	    std::string item;
54	    while (std::getline(ss, item, ',')) {
55	      if (!item.empty()) sizes.push_back(parseU32(item.c_str()));
56	    }
57	    if (sizes.empty()) throw std::runtime_error("No sizes provided");
58	    for (uint32_t n : sizes) {
59	      if (n == 0) throw std::runtime_error("N must be positive");
60	    }
61	    return sizes;
62	  }
