64	  uint32_t n_min = kNMin;
65	  uint32_t n_max = kNMax;
66	  int n_count = kNCount;
67	  if (argc == 6) {
68	    n_min = parseU32(argv[3]);
69	    n_max = parseU32(argv[4]);
70	    n_count = static_cast<int>(parseU32(argv[5]));
71	  }
72	
73	  if (n_count <= 0) throw std::runtime_error("n_count must be positive");
74	  if (n_min == 0 || n_max == 0) throw std::runtime_error("N must be positive");
75	  if (n_max < n_min) throw std::runtime_error("n_max must be >= n_min");
76	  std::vector<uint32_t> sizes;
77	  sizes.reserve(static_cast<size_t>(n_count));
78	  uint32_t step = n_count == 1 ? 0 : (n_max - n_min) / static_cast<uint32_t>(n_count - 1);
79	  for (int i = 0; i < n_count; ++i) sizes.push_back(n_min + static_cast<uint32_t>(i) * step);
