105	VulkanBenchmark::VulkanBenchmark() {
106	  volkInitialize();
107	
108	  // instance
109	  VkApplicationInfo application_info = {VK_STRUCTURE_TYPE_APPLICATION_INFO};
110	  application_info.pApplicationName = "vk_radix_sort_benchmark";
111	  application_info.applicationVersion = VK_MAKE_API_VERSION(0, 0, 0, 0);
112	  application_info.pEngineName = "vk_radix_sort";
113	  application_info.engineVersion = VK_MAKE_API_VERSION(0, 0, 0, 0);
114	  application_info.apiVersion = VK_API_VERSION_1_3;
115	
116	  VkDebugUtilsMessengerCreateInfoEXT messenger_info = {
117	      VK_STRUCTURE_TYPE_DEBUG_UTILS_MESSENGER_CREATE_INFO_EXT};
118	  messenger_info.messageSeverity = VK_DEBUG_UTILS_MESSAGE_SEVERITY_VERBOSE_BIT_EXT |
119	                                   VK_DEBUG_UTILS_MESSAGE_SEVERITY_WARNING_BIT_EXT |
120	                                   VK_DEBUG_UTILS_MESSAGE_SEVERITY_ERROR_BIT_EXT;
121	  messenger_info.messageType = VK_DEBUG_UTILS_MESSAGE_TYPE_VALIDATION_BIT_EXT |
122	                               VK_DEBUG_UTILS_MESSAGE_TYPE_PERFORMANCE_BIT_EXT;
123	  messenger_info.pfnUserCallback = DebugCallback;
124	
125	  std::vector<const char*> layers = {};
126	  std::vector<const char*> instance_extensions = {
127	      VK_EXT_DEBUG_UTILS_EXTENSION_NAME,
128	#ifdef __APPLE__
129	      VK_KHR_PORTABILITY_ENUMERATION_EXTENSION_NAME,
130	#endif
131	  };
132	
133	  VkInstanceCreateInfo instance_info = {VK_STRUCTURE_TYPE_INSTANCE_CREATE_INFO};
134	#ifdef __APPLE__
135	  instance_info.flags = VK_INSTANCE_CREATE_ENUMERATE_PORTABILITY_BIT_KHR;
136	#endif
137	  instance_info.pNext = &messenger_info;
138	  instance_info.pApplicationInfo = &application_info;
139	  instance_info.enabledLayerCount = layers.size();
140	  instance_info.ppEnabledLayerNames = layers.data();
141	  instance_info.enabledExtensionCount = instance_extensions.size();
142	  instance_info.ppEnabledExtensionNames = instance_extensions.data();
143	  vkCreateInstance(&instance_info, NULL, &instance_);
144	  volkLoadInstance(instance_);
145	
146	  CreateDebugUtilsMessengerEXT(instance_, &messenger_info, NULL, &messenger_);
147	
148	  // physical device
149	  uint32_t physical_device_count = 0;
150	  vkEnumeratePhysicalDevices(instance_, &physical_device_count, NULL);
151	  std::vector<VkPhysicalDevice> physical_devices(physical_device_count);
152	  vkEnumeratePhysicalDevices(instance_, &physical_device_count, physical_devices.data());
153	  physical_device_ = physical_devices[0];
154	  VkPhysicalDeviceProperties physical_device_properties = {};
155	  vkGetPhysicalDeviceProperties(physical_device_, &physical_device_properties);
156	  timestamp_period_ = physical_device_properties.limits.timestampPeriod;
157	
158	  // find graphics queue
159	  uint32_t queue_family_count = 0;
160	  vkGetPhysicalDeviceQueueFamilyProperties(physical_device_, &queue_family_count, NULL);
161	  std::vector<VkQueueFamilyProperties> queue_families(queue_family_count);
162	  vkGetPhysicalDeviceQueueFamilyProperties(physical_device_, &queue_family_count,
163	                                           queue_families.data());
164	
165	  for (size_t i = 0; i < queue_families.size(); ++i) {
166	    const auto& queue_family = queue_families[i];
167	    if ((queue_family.queueFlags & VK_QUEUE_COMPUTE_BIT) == VK_QUEUE_COMPUTE_BIT &&
168	        (queue_family.queueFlags & VK_QUEUE_GRAPHICS_BIT) == 0) {
169	      queue_family_index_ = i;
170	      break;
171	    }
172	  }
173	
174	  // queues
175	  std::vector<float> queue_priorities = {
176	      1.f,
177	  };
178	  std::vector<VkDeviceQueueCreateInfo> queue_infos(1);
179	  queue_infos[0] = {VK_STRUCTURE_TYPE_DEVICE_QUEUE_CREATE_INFO};
180	  queue_infos[0].queueFamilyIndex = queue_family_index_;
181	  queue_infos[0].queueCount = queue_priorities.size();
182	  queue_infos[0].pQueuePriorities = queue_priorities.data();
183	
184	  uint32_t device_extension_count = 0;
185	  vkEnumerateDeviceExtensionProperties(physical_device_, NULL, &device_extension_count, NULL);
186	  std::vector<VkExtensionProperties> available_device_extensions(device_extension_count);
187	  vkEnumerateDeviceExtensionProperties(physical_device_, NULL, &device_extension_count,
188	                                       available_device_extensions.data());
189	  auto has_device_extension = [&](const char* name) {
190	    return std::any_of(available_device_extensions.begin(), available_device_extensions.end(),
191	                       [&](const VkExtensionProperties& extension) {
192	                         return std::strcmp(extension.extensionName, name) == 0;
193	                       });
194	  };
195	
196	  std::vector<const char*> device_extensions = {
197	#ifdef __APPLE__
198	      "VK_KHR_portability_subset",
199	#endif
200	  };
201	  std::string subgroup_mode = RequestedSubgroupMode();
202	  if (has_device_extension(VK_KHR_PUSH_DESCRIPTOR_EXTENSION_NAME)) {
203	    device_extensions.push_back(VK_KHR_PUSH_DESCRIPTOR_EXTENSION_NAME);
204	  }
205	  if (subgroup_mode != "native" &&
206	      has_device_extension(VK_EXT_SUBGROUP_SIZE_CONTROL_EXTENSION_NAME)) {
207	    device_extensions.push_back(VK_EXT_SUBGROUP_SIZE_CONTROL_EXTENSION_NAME);
208	  }
209	
210	  VkPhysicalDeviceSubgroupSizeControlFeatures subgroup_size_features = {
211	      VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_SIZE_CONTROL_FEATURES};
212	  VkPhysicalDeviceFeatures2 available_features = {VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_FEATURES_2};
213	  available_features.pNext = &subgroup_size_features;
214	  vkGetPhysicalDeviceFeatures2(physical_device_, &available_features);
215	
216	  VkPhysicalDeviceSubgroupSizeControlFeatures enabled_subgroup_size_features = {
217	      VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_SIZE_CONTROL_FEATURES};
218	  if (subgroup_mode != "native") {
219	    enabled_subgroup_size_features.subgroupSizeControl =
220	        subgroup_size_features.subgroupSizeControl;
221	    enabled_subgroup_size_features.computeFullSubgroups =
222	        subgroup_size_features.computeFullSubgroups;
223	  }
224	
225	  VkDeviceCreateInfo device_info = {VK_STRUCTURE_TYPE_DEVICE_CREATE_INFO};
226	  if (enabled_subgroup_size_features.subgroupSizeControl) {
227	    device_info.pNext = &enabled_subgroup_size_features;
228	  }
229	  device_info.queueCreateInfoCount = queue_infos.size();
230	  device_info.pQueueCreateInfos = queue_infos.data();
231	  device_info.enabledExtensionCount = device_extensions.size();
232	  device_info.ppEnabledExtensionNames = device_extensions.data();
233	  vkCreateDevice(physical_device_, &device_info, NULL, &device_);
234	  volkLoadDevice(device_);
235	
236	  vkGetDeviceQueue(device_, queue_family_index_, 0, &queue_);
237	
238	  // vma
239	  VmaVulkanFunctions functions = {};
240	  functions.vkGetInstanceProcAddr = vkGetInstanceProcAddr;
241	  functions.vkGetDeviceProcAddr = vkGetDeviceProcAddr;
242	
243	  VmaAllocatorCreateInfo allocator_info = {};
244	  allocator_info.physicalDevice = physical_device_;
245	  allocator_info.device = device_;
246	  allocator_info.instance = instance_;
247	  allocator_info.pVulkanFunctions = &functions;
248	  allocator_info.vulkanApiVersion = application_info.apiVersion;
249	  vmaCreateAllocator(&allocator_info, &allocator_);
250	
251	  // commands
252	  VkCommandPoolCreateInfo command_pool_info = {VK_STRUCTURE_TYPE_COMMAND_POOL_CREATE_INFO};
253	  command_pool_info.flags =
254	      VK_COMMAND_POOL_CREATE_RESET_COMMAND_BUFFER_BIT | VK_COMMAND_POOL_CREATE_TRANSIENT_BIT;
255	  command_pool_info.queueFamilyIndex = queue_family_index_;
256	  vkCreateCommandPool(device_, &command_pool_info, NULL, &command_pool_);
257	
258	  VkCommandBufferAllocateInfo command_buffer_info = {
259	      VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
260	  command_buffer_info.commandPool = command_pool_;
261	  command_buffer_info.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
262	  command_buffer_info.commandBufferCount = 1;
263	  vkAllocateCommandBuffers(device_, &command_buffer_info, &command_buffer_);
264	
265	  // fence
266	  VkFenceCreateInfo fence_info = {VK_STRUCTURE_TYPE_FENCE_CREATE_INFO};
267	  vkCreateFence(device_, &fence_info, NULL, &fence_);
268	
269	  // timestamp query pool
270	  VkQueryPoolCreateInfo query_pool_info = {VK_STRUCTURE_TYPE_QUERY_POOL_CREATE_INFO};
271	  query_pool_info.queryType = VK_QUERY_TYPE_TIMESTAMP;
272	  query_pool_info.queryCount = timestamp_count;
273	  vkCreateQueryPool(device_, &query_pool_info, NULL, &query_pool_);
274	
275	  // sorter
276	  VrdxSorterCreateInfo sorter_info = {};
277	  sorter_info.physicalDevice = physical_device_;
278	  sorter_info.device = device_;
279	
280	  VkPhysicalDeviceSubgroupSizeControlProperties subgroup_size_properties = {
281	      VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_SIZE_CONTROL_PROPERTIES};
282	  VkPhysicalDeviceSubgroupProperties subgroup_properties = {
283	      VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_SUBGROUP_PROPERTIES};
284	  VkPhysicalDeviceProperties2 properties = {VK_STRUCTURE_TYPE_PHYSICAL_DEVICE_PROPERTIES_2};
285	  properties.pNext = &subgroup_properties;
286	  subgroup_properties.pNext = &subgroup_size_properties;
287	  vkGetPhysicalDeviceProperties2(physical_device_, &properties);
288	
289	  const bool can_require_subgroup =
290	      enabled_subgroup_size_features.subgroupSizeControl &&
291	      (subgroup_size_properties.requiredSubgroupSizeStages & VK_SHADER_STAGE_COMPUTE_BIT);
292	  uint32_t requested_subgroup_size = 0;
293	  if (subgroup_mode == "auto") {
294	    if (can_require_subgroup && subgroup_size_properties.minSubgroupSize <= 32 &&
295	        subgroup_size_properties.maxSubgroupSize >= 32) {
296	      requested_subgroup_size = 32;
297	    }
298	  } else if (subgroup_mode != "native") {
299	    char* end = nullptr;
300	    unsigned long value = std::strtoul(subgroup_mode.c_str(), &end, 10);
301	    if (end == subgroup_mode.c_str() || *end != '\0' || value > UINT32_MAX) {
302	      throw std::runtime_error("VRDX_SUBGROUP_SIZE must be auto, native, or a positive integer");
303	    }
304	    requested_subgroup_size = static_cast<uint32_t>(value);
305	    if (!can_require_subgroup ||
306	        requested_subgroup_size < subgroup_size_properties.minSubgroupSize ||
307	        requested_subgroup_size > subgroup_size_properties.maxSubgroupSize ||
308	        requested_subgroup_size < 32 || kWorkgroupSize % requested_subgroup_size != 0) {
309	      throw std::runtime_error("Requested Vulkan subgroup size is unsupported by this device");
310	    }
311	  }
312	
313	  subgroup_size_ =
314	      requested_subgroup_size ? requested_subgroup_size : subgroup_properties.subgroupSize;
315	  required_subgroup_size_ = requested_subgroup_size;
316	  if (subgroup_size_ < 32 || kWorkgroupSize % subgroup_size_ != 0) {
317	    throw std::runtime_error("vk_radix_sort requires a compute subgroup size of at least 32");
318	  }
319	  sorter_info.requiredSubgroupSize = required_subgroup_size_;
320	  std::cout << "Vulkan subgroup: native=" << subgroup_properties.subgroupSize
321	            << " selected=" << subgroup_size_
322	            << (required_subgroup_size_ ? " (required)" : " (native)") << std::endl;
323	  vrdxCreateSorter(&sorter_info, &sorter_);
324	}
