326	VulkanBenchmark::~VulkanBenchmark() {
327	  vkDeviceWaitIdle(device_);
328	
329	  if (keys_.buffer) vmaDestroyBuffer(allocator_, keys_.buffer, keys_.allocation);
330	  if (storage_.buffer) vmaDestroyBuffer(allocator_, storage_.buffer, storage_.allocation);
331	  if (staging_.buffer) vmaDestroyBuffer(allocator_, staging_.buffer, staging_.allocation);
332	
333	  vrdxDestroySorter(sorter_);
334	  vkDestroyQueryPool(device_, query_pool_, NULL);
335	  vkDestroyFence(device_, fence_, NULL);
336	  vkDestroyCommandPool(device_, command_pool_, NULL);
337	  vmaDestroyAllocator(allocator_);
338	  vkDestroyDevice(device_, NULL);
339	  DestroyDebugUtilsMessengerEXT(instance_, messenger_, NULL);
340	  vkDestroyInstance(instance_, NULL);
341	
342	  volkFinalize();
343	}
