345	void VulkanBenchmark::Reallocate(Buffer* buffer, VkDeviceSize size, VkBufferUsageFlags usage,
346	                                 bool mapped) {
347	  if ((buffer->usage & usage) == usage && buffer->size >= size &&
348	      (mapped && buffer->map || !mapped && buffer->map == nullptr))
349	    return;
350	
351	  if (buffer->allocation) vmaDestroyBuffer(allocator_, buffer->buffer, buffer->allocation);
352	
353	  VkBufferCreateInfo buffer_info = {VK_STRUCTURE_TYPE_BUFFER_CREATE_INFO};
354	  buffer_info.size = size;
355	  buffer_info.usage = usage;
356	  VmaAllocationCreateInfo allocation_create_info = {};
357	  if (mapped) {
358	    allocation_create_info.flags =
359	        VMA_ALLOCATION_CREATE_HOST_ACCESS_RANDOM_BIT | VMA_ALLOCATION_CREATE_MAPPED_BIT;
360	  }
361	  allocation_create_info.usage = VMA_MEMORY_USAGE_AUTO;
362	
363	  VmaAllocationInfo allocation_info;
364	  vmaCreateBuffer(allocator_, &buffer_info, &allocation_create_info, &buffer->buffer,
365	                  &buffer->allocation, &allocation_info);
366	
367	  buffer->usage = usage;
368	  buffer->size = size;
369	  if (mapped) buffer->map = reinterpret_cast<uint8_t*>(allocation_info.pMappedData);
370	}
