372	bool VulkanBenchmark::RunSubmissionStress(uint32_t runs, uint32_t batch_size) {
373	  if (runs == 0 || batch_size == 0) {
374	    throw std::runtime_error("Submission stress runs and batch size must be positive");
375	  }
376	
377	  auto begin_command_buffer = [&](VkCommandBuffer command_buffer,
378	                                  VkCommandBufferUsageFlags flags) {
379	    vkResetCommandBuffer(command_buffer, 0);
380	    VkCommandBufferBeginInfo begin_info = {VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
381	    begin_info.flags = flags;
382	    VkResult result = vkBeginCommandBuffer(command_buffer, &begin_info);
383	    if (result != VK_SUCCESS) {
384	      throw std::runtime_error("vkBeginCommandBuffer failed with VkResult " +
385	                               std::to_string(result));
386	    }
387	  };
388	
389	  auto submit_and_wait = [&](const std::vector<VkCommandBuffer>& command_buffers,
390	                             const char* stage) {
391	    VkSubmitInfo submit = {VK_STRUCTURE_TYPE_SUBMIT_INFO};
392	    submit.commandBufferCount = static_cast<uint32_t>(command_buffers.size());
393	    submit.pCommandBuffers = command_buffers.data();
394	    VkResult result = vkQueueSubmit(queue_, 1, &submit, fence_);
395	    if (result != VK_SUCCESS) {
396	      throw std::runtime_error(std::string("vkQueueSubmit failed during ") + stage +
397	                               " with VkResult " + std::to_string(result));
398	    }
399	    WaitForFence(device_, fence_, stage);
400	    vkResetFences(device_, 1, &fence_);
401	  };
402	
403	  auto chain_barrier = [](VkCommandBuffer command_buffer) {
404	    VkMemoryBarrier barrier = {VK_STRUCTURE_TYPE_MEMORY_BARRIER};
405	    barrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT | VK_ACCESS_SHADER_WRITE_BIT;
406	    barrier.dstAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT | VK_ACCESS_SHADER_READ_BIT |
407	                            VK_ACCESS_SHADER_WRITE_BIT;
408	    vkCmdPipelineBarrier(command_buffer,
409	                         VK_PIPELINE_STAGE_TRANSFER_BIT |
410	                             VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
411	                         VK_PIPELINE_STAGE_TRANSFER_BIT |
412	                             VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
413	                         0, 1, &barrier, 0, nullptr, 0, nullptr);
414	  };
415	
416	  for (uint32_t run = 0; run < runs; ++run) {
417	    uint32_t element_count = run % 2 == 0 ? 262145u : 65537u;
418	    uint32_t inout_size =
419	        std::max(Align(element_count * static_cast<uint32_t>(sizeof(uint32_t)), 16), 16u);
420	
421	    std::vector<uint32_t> input_keys(element_count);
422	    std::vector<uint32_t> input_values(element_count);
423	    for (uint32_t i = 0; i < element_count; ++i) {
424	      input_keys[i] = ((i * 2654435761u) ^ (run * 2246822519u)) & 0xffu;
425	      input_values[i] = i;
426	    }
427	
428	    std::vector<uint32_t> expected_keys = input_keys;
429	    std::sort(expected_keys.begin(), expected_keys.end());
430	    std::vector<std::pair<uint32_t, uint32_t>> expected_pairs(element_count);
431	    for (uint32_t i = 0; i < element_count; ++i) {
432	      expected_pairs[i] = {input_keys[i], input_values[i]};
433	    }
434	    std::stable_sort(expected_pairs.begin(), expected_pairs.end(),
435	                     [](const auto& a, const auto& b) { return a.first < b.first; });
436	
437	    Reallocate(&staging_, 2 * inout_size,
438	               VK_BUFFER_USAGE_TRANSFER_SRC_BIT | VK_BUFFER_USAGE_TRANSFER_DST_BIT, true);
439	    Reallocate(&keys_, 2 * inout_size,
440	               VK_BUFFER_USAGE_STORAGE_BUFFER_BIT | VK_BUFFER_USAGE_TRANSFER_SRC_BIT |
441	                   VK_BUFFER_USAGE_TRANSFER_DST_BIT);
442	    VrdxSorterStorageRequirements requirements;
443	    vrdxGetSorterKeyValueStorageRequirements(sorter_, element_count, &requirements);
444	    Reallocate(&storage_, requirements.size, requirements.usage);
445	
446	    auto upload = [&] {
447	      std::memcpy(staging_.map, input_keys.data(), element_count * sizeof(uint32_t));
448	      std::memcpy(staging_.map + inout_size, input_values.data(),
449	                  element_count * sizeof(uint32_t));
450	      vmaFlushAllocation(allocator_, staging_.allocation, 0, 2 * inout_size);
451	
452	      begin_command_buffer(command_buffer_, VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT);
453	      VkBufferCopy copy = {};
454	      copy.size = 2 * inout_size;
455	      vkCmdCopyBuffer(command_buffer_, staging_.buffer, keys_.buffer, 1, &copy);
456	      vkEndCommandBuffer(command_buffer_);
457	      submit_and_wait({command_buffer_}, "submission stress upload");
458	    };
459	
460	    auto read_and_check = [&](bool key_value, const char* mode) {
461	      begin_command_buffer(command_buffer_, VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT);
462	      VkMemoryBarrier barrier = {VK_STRUCTURE_TYPE_MEMORY_BARRIER};
463	      barrier.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
464	      barrier.dstAccessMask = VK_ACCESS_TRANSFER_READ_BIT;
465	      vkCmdPipelineBarrier(command_buffer_, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
466	                           VK_PIPELINE_STAGE_TRANSFER_BIT, 0, 1, &barrier, 0, nullptr, 0,
467	                           nullptr);
468	      VkBufferCopy copy = {};
469	      copy.size = key_value ? 2 * inout_size : inout_size;
470	      vkCmdCopyBuffer(command_buffer_, keys_.buffer, staging_.buffer, 1, &copy);
471	      vkEndCommandBuffer(command_buffer_);
472	      submit_and_wait({command_buffer_}, "submission stress readback");
473	
474	      vmaInvalidateAllocation(allocator_, staging_.allocation, 0, copy.size);
475	      const uint32_t* output_keys = reinterpret_cast<const uint32_t*>(staging_.map);
476	      for (uint32_t i = 0; i < element_count; ++i) {
477	        uint32_t expected_key = key_value ? expected_pairs[i].first : expected_keys[i];
478	        if (output_keys[i] != expected_key) {
479	          std::cerr << mode << " key mismatch at " << i << std::endl;
480	          return false;
481	        }
482	      }
483	      if (key_value) {
484	        const uint32_t* output_values =
485	            reinterpret_cast<const uint32_t*>(staging_.map + inout_size);
486	        for (uint32_t i = 0; i < element_count; ++i) {
487	          if (output_values[i] != expected_pairs[i].second) {
488	            std::cerr << mode << " value mismatch at " << i << std::endl;
489	            return false;
490	          }
491	        }
492	      }
493	      return true;
494	    };
495	
496	    auto record_sort = [&](VkCommandBuffer command_buffer, bool key_value,
497	                           uint32_t repeat_count) {
498	      begin_command_buffer(command_buffer, VK_COMMAND_BUFFER_USAGE_ONE_TIME_SUBMIT_BIT);
499	      chain_barrier(command_buffer);
500	      for (uint32_t i = 0; i < repeat_count; ++i) {
501	        if (key_value) {
502	          vrdxCmdSortKeyValue(command_buffer, sorter_, element_count, keys_.buffer, 0,
503	                              keys_.buffer, inout_size, storage_.buffer, 0, VK_NULL_HANDLE, 0);
504	        } else {
505	          vrdxCmdSort(command_buffer, sorter_, element_count, keys_.buffer, 0,
506	                      storage_.buffer, 0, VK_NULL_HANDLE, 0);
507	        }
508	        if (i + 1 < repeat_count) chain_barrier(command_buffer);
509	      }
510	      vkEndCommandBuffer(command_buffer);
511	    };
512	
513	    for (bool key_value : {false, true}) {
514	      const char* sort_name = key_value ? "key-value" : "keys";
515	
516	      upload();
517	      record_sort(command_buffer_, key_value, batch_size);
518	      submit_and_wait({command_buffer_}, "same-command-buffer sort chain");
519	      if (!read_and_check(key_value, "same-command-buffer")) return false;
520	      std::cout << "Submission stress run " << run + 1 << "/" << runs << " " << sort_name
521	                << " same-command-buffer passed" << std::endl;
522	
523	      upload();
524	      std::vector<VkCommandBuffer> command_buffers(batch_size);
525	      VkCommandBufferAllocateInfo allocate_info = {
526	          VK_STRUCTURE_TYPE_COMMAND_BUFFER_ALLOCATE_INFO};
527	      allocate_info.commandPool = command_pool_;
528	      allocate_info.level = VK_COMMAND_BUFFER_LEVEL_PRIMARY;
529	      allocate_info.commandBufferCount = batch_size;
530	      VkResult result =
531	          vkAllocateCommandBuffers(device_, &allocate_info, command_buffers.data());
532	      if (result != VK_SUCCESS) {
533	        throw std::runtime_error("vkAllocateCommandBuffers failed with VkResult " +
534	                                 std::to_string(result));
535	      }
536	      for (VkCommandBuffer command_buffer : command_buffers) {
537	        record_sort(command_buffer, key_value, 1);
538	      }
539	      submit_and_wait(command_buffers, "multi-command-buffer sort chain");
540	      vkFreeCommandBuffers(device_, command_pool_, batch_size, command_buffers.data());
541	      if (!read_and_check(key_value, "multi-command-buffer")) return false;
542	      std::cout << "Submission stress run " << run + 1 << "/" << runs << " " << sort_name
543	                << " multi-command-buffer passed" << std::endl;
544	
545	      upload();
546	      command_buffers.resize(batch_size);
547	      result = vkAllocateCommandBuffers(device_, &allocate_info, command_buffers.data());
548	      if (result != VK_SUCCESS) {
549	        throw std::runtime_error("vkAllocateCommandBuffers failed with VkResult " +
550	                                 std::to_string(result));
551	      }
552	      for (VkCommandBuffer command_buffer : command_buffers) {
553	        record_sort(command_buffer, key_value, 1);
554	      }
555	      for (uint32_t i = 0; i < batch_size; ++i) {
556	        VkSubmitInfo submit = {VK_STRUCTURE_TYPE_SUBMIT_INFO};
557	        submit.commandBufferCount = 1;
558	        submit.pCommandBuffers = &command_buffers[i];
559	        VkFence submit_fence = i + 1 == batch_size ? fence_ : VK_NULL_HANDLE;
560	        result = vkQueueSubmit(queue_, 1, &submit, submit_fence);
561	        if (result != VK_SUCCESS) {
562	          throw std::runtime_error("vkQueueSubmit failed during no-wait chain with VkResult " +
563	                                   std::to_string(result));
564	        }
565	      }
566	      WaitForFence(device_, fence_, "no-wait multi-submit sort chain");
567	      vkResetFences(device_, 1, &fence_);
568	      vkFreeCommandBuffers(device_, command_pool_, batch_size, command_buffers.data());
569	      if (!read_and_check(key_value, "no-wait-multi-submit")) return false;
570	      std::cout << "Submission stress run " << run + 1 << "/" << runs << " " << sort_name
571	                << " no-wait-multi-submit passed" << std::endl;
572	    }
573	  }
574	
575	  std::cout << "Submission stress passed: subgroup=" << subgroup_size_ << " runs=" << runs
576	            << " batch=" << batch_size << std::endl;
577	  return true;
578	}
