void MultiRadixSortPass::recordAllIterations(VkCommandBuffer commandBuffer, uint32_t baseActiveIndex) {
    const uint32_t NUM_ITERATIONS = 4;

    for (uint32_t i = 0; i < NUM_ITERATIONS; i++) {
        uint32_t frameIdx = (baseActiveIndex + i) % 2;
        const auto& descSets = m_descriptorSets[frameIdx];

        // Setup overhead only on first iteration
        if (i == 0 && m_doSetupOverhead && m_setupFillBuffer != VK_NULL_HANDLE && m_setupUpdateBuffer != VK_NULL_HANDLE) {
            uint32_t elementCount = m_pushConstantsHistogram.g_num_elements;
            vkCmdUpdateBuffer(commandBuffer, m_setupUpdateBuffer, 0, sizeof(elementCount), &elementCount);
            vkCmdFillBuffer(commandBuffer, m_setupFillBuffer, 0, 4 * 256 * sizeof(uint32_t), 0);
            VkMemoryBarrier setupBarrier{VK_STRUCTURE_TYPE_MEMORY_BARRIER};
            setupBarrier.srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT;
            setupBarrier.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
            vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_TRANSFER_BIT,
                                 VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &setupBarrier, 0, nullptr, 0, nullptr);
            m_doSetupOverhead = false;
        }

        // Update push constants for this iteration
        m_pushConstantsHistogram.g_shift = 8 * i;
        m_pushConstants.g_shift = 8 * i;

        // Histogram dispatch
        vkCmdPushConstants(commandBuffer, m_pipelineLayouts[RADIX_SORT_HISTOGRAMS],
                          VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PushConstantsHistograms), &m_pushConstantsHistogram);
        vkCmdBindPipeline(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, m_pipelines[RADIX_SORT_HISTOGRAMS]);
        vkCmdBindDescriptorSets(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE,
                               m_pipelineLayouts[RADIX_SORT_HISTOGRAMS], 0,
                               descSets.size(), descSets.data(), 0, nullptr);
        vkCmdDispatch(commandBuffer, m_workGroupCounts[RADIX_SORT_HISTOGRAMS].width, 1, 1);

        // Barrier: histogram writes → scatter reads
        VkMemoryBarrier barrier{VK_STRUCTURE_TYPE_MEMORY_BARRIER};
        barrier.srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT;
        barrier.dstAccessMask = VK_ACCESS_SHADER_READ_BIT;
        vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
                            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &barrier, 0, nullptr, 0, nullptr);

        // Scatter dispatch
        vkCmdPushConstants(commandBuffer, m_pipelineLayouts[RADIX_SORT],
                          VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PushConstants), &m_pushConstants);
        vkCmdBindPipeline(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, m_pipelines[RADIX_SORT]);
        vkCmdBindDescriptorSets(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE,
                               m_pipelineLayouts[RADIX_SORT], 0,
                               descSets.size(), descSets.data(), 0, nullptr);
        vkCmdDispatch(commandBuffer, m_workGroupCounts[RADIX_SORT].width, 1, 1);

        // Barrier between iterations (not needed after last)
        if (i < NUM_ITERATIONS - 1) {
            vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
                                VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &barrier, 0, nullptr, 0, nullptr);
        }
    }
}
```

