void MultiRadixSortPass::executeSingleSubmit(VkQueryPool queryPool, uint32_t startQuery, uint32_t endQuery) {
    uint32_t activeIndex = m_gpuContext->getActiveIndex();

    // Wait for previous work to complete
    vkWaitForFences(m_gpuContext->m_device, 1, &m_fences[activeIndex], VK_TRUE, UINT64_MAX);
    vkResetFences(m_gpuContext->m_device, 1, &m_fences[activeIndex]);

    // Reset and begin command buffer
    vkResetCommandBuffer(m_commandBuffers[activeIndex], 0);
    VkCommandBufferBeginInfo beginInfo{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    vkBeginCommandBuffer(m_commandBuffers[activeIndex], &beginInfo);

    // Start timestamp
    vkCmdWriteTimestamp(m_commandBuffers[activeIndex], VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, queryPool, startQuery);

    // Record all 4 iterations
    recordAllIterations(m_commandBuffers[activeIndex], activeIndex);

    // End timestamp
    vkCmdWriteTimestamp(m_commandBuffers[activeIndex], VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, queryPool, endQuery);

    vkEndCommandBuffer(m_commandBuffers[activeIndex]);

    // Submit once (no semaphores)
    VkSubmitInfo submitInfo{VK_STRUCTURE_TYPE_SUBMIT_INFO};
    submitInfo.commandBufferCount = 1;
    submitInfo.pCommandBuffers = &m_commandBuffers[activeIndex];
    vkQueueSubmit(m_gpuContext->m_queues->getQueue(Queues::COMPUTE), 1, &submitInfo, m_fences[activeIndex]);
