void MultiRadixSortPass::recordAllIterations(VkCommandBuffer commandBuffer, uint32_t baseActiveIndex) {
    const uint32_t NUM_ITERATIONS = 4;

    for (uint32_t i = 0; i < NUM_ITERATIONS; i++) {
        // Alternate descriptor sets for ping-pong buffer swapping
        uint32_t frameIdx = (baseActiveIndex + i) % 2;
        const auto& descSets = m_descriptorSets[frameIdx];

        // Setup overhead on first iteration only (fair comparison with VRDX)
        if (i == 0 && m_doSetupOverhead && m_setupFillBuffer != VK_NULL_HANDLE && m_setupUpdateBuffer != VK_NULL_HANDLE) {
            uint32_t elementCount = m_pushConstantsHistogram.g_num_elements;
            vkCmdUpdateBuffer(commandBuffer, m_setupUpdateBuffer, 0, sizeof(elementCount), &elementCount);
            vkCmdFillBuffer(commandBuffer, m_setupFillBuffer, 0, 4 * 256 * sizeof(uint32_t), 0);
            VkMemoryBarrier setupBarrier{.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER,
                .srcAccessMask = VK_ACCESS_TRANSFER_WRITE_BIT,
                .dstAccessMask = VK_ACCESS_SHADER_READ_BIT};
            vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_TRANSFER_BIT,
                VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &setupBarrier, 0, nullptr, 0, nullptr);
            m_doSetupOverhead = false;
        }

        // Push constants with correct shift for this iteration
        PushConstantsHistograms histPC = m_pushConstantsHistogram;
        histPC.g_shift = 8 * i;
        PushConstants scatterPC = m_pushConstants;
        scatterPC.g_shift = 8 * i;

        // --- Histogram dispatch ---
        vkCmdPushConstants(commandBuffer, m_pipelineLayouts[RADIX_SORT_HISTOGRAMS],
            VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PushConstantsHistograms), &histPC);
        vkCmdBindPipeline(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, m_pipelines[RADIX_SORT_HISTOGRAMS]);
        vkCmdBindDescriptorSets(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE,
            m_pipelineLayouts[RADIX_SORT_HISTOGRAMS], 0,
            static_cast<uint32_t>(descSets.size()), descSets.data(), 0, nullptr);
        VkExtent3D histWG = getWorkGroupCount(RADIX_SORT_HISTOGRAMS);
        vkCmdDispatch(commandBuffer, histWG.width, histWG.height, histWG.depth);

        // Barrier: histogram writes → scatter reads
        VkMemoryBarrier barrier{.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER,
            .srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT,
            .dstAccessMask = VK_ACCESS_SHADER_READ_BIT};
        vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
            VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &barrier, 0, nullptr, 0, nullptr);

        // --- Scatter dispatch ---
        vkCmdPushConstants(commandBuffer, m_pipelineLayouts[RADIX_SORT],
            VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PushConstants), &scatterPC);
        vkCmdBindPipeline(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE, m_pipelines[RADIX_SORT]);
        vkCmdBindDescriptorSets(commandBuffer, VK_PIPELINE_BIND_POINT_COMPUTE,
            m_pipelineLayouts[RADIX_SORT], 0,
            static_cast<uint32_t>(descSets.size()), descSets.data(), 0, nullptr);
        VkExtent3D scatterWG = getWorkGroupCount(RADIX_SORT);
        vkCmdDispatch(commandBuffer, scatterWG.width, scatterWG.height, scatterWG.depth);

        // Barrier between iterations (scatter writes → next histogram reads)
        if (i < NUM_ITERATIONS - 1) {
            VkMemoryBarrier iterBarrier{.sType = VK_STRUCTURE_TYPE_MEMORY_BARRIER,
                .srcAccessMask = VK_ACCESS_SHADER_WRITE_BIT,
                .dstAccessMask = VK_ACCESS_SHADER_READ_BIT};
            vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT,
                VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, 0, 1, &iterBarrier, 0, nullptr, 0, nullptr);
        }
    }
}

void MultiRadixSortPass::executeSingleSubmit(VkQueryPool queryPool, uint32_t startQuery, uint32_t endQuery) {
    uint32_t activeIndex = m_gpuContext->getActiveIndex();

    // Wait for previous work
    vkWaitForFences(m_gpuContext->m_device, 1, &m_fences[activeIndex], VK_TRUE, UINT64_MAX);
    vkResetFences(m_gpuContext->m_device, 1, &m_fences[activeIndex]);

    // Record into one command buffer
    vkResetCommandBuffer(m_commandBuffers[activeIndex], 0);
    VkCommandBufferBeginInfo beginInfo{VK_STRUCTURE_TYPE_COMMAND_BUFFER_BEGIN_INFO};
    vkBeginCommandBuffer(m_commandBuffers[activeIndex], &beginInfo);

    vkCmdWriteTimestamp(m_commandBuffers[activeIndex], VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, queryPool, startQuery);

    recordAllIterations(m_commandBuffers[activeIndex], activeIndex);

    vkCmdWriteTimestamp(m_commandBuffers[activeIndex], VK_PIPELINE_STAGE_ALL_COMMANDS_BIT, queryPool, endQuery);

    vkEndCommandBuffer(m_commandBuffers[activeIndex]);

    // Single submit — no semaphores
    VkSubmitInfo submitInfo{VK_STRUCTURE_TYPE_SUBMIT_INFO};
    submitInfo.commandBufferCount = 1;
    submitInfo.pCommandBuffers = &m_commandBuffers[activeIndex];
    vkQueueSubmit(m_gpuContext->m_queues->getQueue(Queues::COMPUTE), 1, &submitInfo, m_fences[activeIndex]);
}

void MultiRadixSortPass::recordCommands(VkCommandBuffer commandBuffer) {
    // Legacy path — not used in single-submit mode, kept for compatibility
    vkCmdPushConstants(commandBuffer, m_pipelineLayouts[RADIX_SORT_HISTOGRAMS], VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PushConstantsHistograms), &m_pushConstantsHistogram);
    recordCommandComputeShaderExecution(commandBuffer, RADIX_SORT_HISTOGRAMS);
    VkMemoryBarrier memoryBarrier0{.sType=VK_STRUCTURE_TYPE_MEMORY_BARRIER, .srcAccessMask=VK_ACCESS_SHADER_WRITE_BIT, .dstAccessMask=VK_ACCESS_SHADER_READ_BIT};
    vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, {}, 1, &memoryBarrier0, 0, nullptr, 0, nullptr);

    vkCmdPushConstants(commandBuffer, m_pipelineLayouts[RADIX_SORT], VK_SHADER_STAGE_COMPUTE_BIT, 0, sizeof(PushConstants), &m_pushConstants);
    recordCommandComputeShaderExecution(commandBuffer, RADIX_SORT);
    VkMemoryBarrier memoryBarrier1{.sType=VK_STRUCTURE_TYPE_MEMORY_BARRIER, .srcAccessMask=VK_ACCESS_SHADER_WRITE_BIT, .dstAccessMask=VK_ACCESS_SHADER_READ_BIT};
    vkCmdPipelineBarrier(commandBuffer, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, VK_PIPELINE_STAGE_COMPUTE_SHADER_BIT, {}, 1, &memoryBarrier1, 0, nullptr, 0, nullptr);
}

